from pathlib import Path
import json,html,os,shutil
from urllib.parse import urlsplit
from site_config import load_settings, production_policies, business_details
ROOT=Path(__file__).resolve().parent.parent
DIST=ROOT/'dist'
ORIGIN=os.environ.get('SITE_ORIGIN','http://localhost:3000').rstrip('/')
parsed_origin=urlsplit(ORIGIN)
if parsed_origin.scheme not in ('http','https') or not parsed_origin.netloc or parsed_origin.path or parsed_origin.query or parsed_origin.fragment:
 raise SystemExit('SITE_ORIGIN must be an http(s) origin without a path, query or fragment.')
PUBLISHED=os.environ.get('SITE_INDEXABLE','false').lower()=='true'
LIVE=os.environ.get('SITE_LIVE','false').lower()=='true'
SETTINGS=load_settings(ROOT,LIVE,PUBLISHED)
BRAND=SETTINGS['brand']
if (PUBLISHED or LIVE) and (parsed_origin.hostname in ('localhost','127.0.0.1') or parsed_origin.scheme!='https'):
 raise SystemExit('Live or indexable builds require a real HTTPS SITE_ORIGIN.')
if DIST.exists():shutil.rmtree(DIST)
shutil.copytree(ROOT/'public',DIST)
