def icon(name):return f'<svg class="ico" aria-hidden="true" viewBox="0 0 24 24">{icons.get(name,icons["car"])}</svg>'
def arrow():return icon('arrow')
def link(label,url,cls='text-link'):return f'<a class="{cls}" href="{url}">{label}{arrow()}</a>'
def logo():return f'<a class="logo" href="/" aria-label="ScrapLocal home"><span class="logo-mark">{icon("recycle")}</span>scrap<em>local</em></a>'
def start_form(key='main', label='Enter your car registration', show_note=True):
 note = f'<p class="micro">{icon("lock")} No obligation. No phone number needed to get started.</p>' if show_note else ''
 return f'''<form class="reg-start" action="/quote/" method="get" data-reg-start><div class="reg-row"><div class="registration-entry"><label for="reg-{key}">{label}</label><div class="plate"><div class="gb" aria-hidden="true"><span>✦</span>UK</div><input id="reg-{key}" name="reg" required maxlength="10" placeholder="ENTER REG" aria-describedby="reg-error-{key}" autocomplete="off" spellcheck="false" autocapitalize="characters" aria-label="Car registration"></div></div><button class="btn" type="submit" disabled>Get my quote {arrow()}</button></div><noscript><p class="error">Enable JavaScript to continue with your registration.</p></noscript><p id="reg-error-{key}" class="error" aria-live="polite" hidden></p>{note}</form>'''

locations={
'birmingham':{'name':'Birmingham','area':'Birmingham and its neighbourhoods','places':['Erdington','Edgbaston','Harborne','Kings Heath','Selly Oak','Great Barr'],'intro':'A car taking up space on a Birmingham driveway? Whether it has failed its MOT, stopped starting or simply reached the end of the road, start with your registration and request a collection quote.','heading':'A simpler way to move on in Birmingham','body':'From a tight residential street in Harborne to a driveway in Great Barr, access matters when arranging vehicle recovery. Tell us the collection postcode first. Before booking, the collection team will need to confirm where the car is parked and whether a recovery vehicle can reach it.','detail':'If your car is in a shared car park, underground space or on a busy road, mention this when collection is arranged. Do not drive an unroadworthy car to a collection point.','tip':'Keeping a Birmingham car off the road? Make sure the collection location is accessible and that you have permission for the vehicle to be removed.'},
'west-bromwich':{'name':'West Bromwich','area':'West Bromwich and Sandwell','places':['Stone Cross','Charlemont','Hill Top','Great Bridge','Lyndon','Greets Green'],'intro':'Ready to clear that space on the drive? Request a scrap car quote in West Bromwich, including Stone Cross, Hill Top and the surrounding Sandwell area. Your registration is all you need to get started.','heading':'Scrap car collection around Sandwell','body':'If your car is at home in Stone Cross or parked near a workshop in Hill Top, use the postcode where it will actually be collected. Your home address and the vehicle location may be different, and the right postcode helps the collection team plan the job.','detail':'Cars with no battery, missing wheels or steering issues can need different recovery equipment. Choose “Missing parts” in the quote form if components have been removed, then explain the details before collection is booked.','tip':'If your car is waiting at a garage, agree its release with the garage before arranging collection. Any outstanding storage or repair fees are separate from a scrap quote.'},
'dudley':{'name':'Dudley','area':'Dudley and the surrounding Black Country','places':['Sedgley','Gornal','Netherton','Coseley','Dudley Port','Woodsetton'],'intro':'An MOT failure or a car that no longer runs does not have to stay on your drive. Request a scrap car quote for collection in Dudley and the surrounding Black Country.','heading':'A practical plan for your Dudley collection','body':'Steep drives, narrow lanes and shared parking can affect how a car is recovered. Add the collection postcode to your request, then confirm access and whether the vehicle rolls and steers before agreeing a collection slot.','detail':'If the vehicle has been stationary for a long time, tell the collection team about flat tyres or seized brakes. A non-runner and a car that cannot move at all may require different equipment.','tip':'Keep the keys safe even if the engine no longer starts. They can still help the collection driver unlock the car and release the steering.'},
'walsall':{'name':'Walsall','area':'Walsall and nearby neighbourhoods','places':['Bloxwich','Pelsall','Aldridge','Bescot','Darlaston','Willenhall'],'intro':'Replacing an older car in Walsall? Tell us the registration, condition and collection postcode to prepare your quote request, without having to add a phone number.','heading':'Your Walsall car, your next step','body':'The vehicle may be on your driveway, outside a garage or on private land elsewhere in Walsall. Use the postcode of the car itself, so collection availability can be checked for the right place.','detail':'If a family member or garage will hand over the car for you, agree that arrangement with the collection team first. Ownership checks and the required documents must be confirmed before any vehicle changes hands.','tip':'Take personal belongings out of the car in advance, including items in the glovebox, boot and door pockets. Check any connected dashcam or parking account too.'},
'wolverhampton':{'name':'Wolverhampton','area':'Wolverhampton and the surrounding area','places':['Tettenhall','Penn','Bilston','Wednesfield','Bushbury','Fallings Park'],'intro':'From a non-runner in Penn to an older car in Wednesfield, the first step is the same: enter your registration and tell us a little about the vehicle for a collection quote.','heading':'Make room for what comes next','body':'A complete car that runs, a non-runner and a damaged vehicle can each need a different approach. Choose the closest condition in the form. The final quote and collection arrangements should reflect the car as it is today.','detail':'If your car has a private registration you want to keep, arrange retention with DVLA before the vehicle is transferred. Do this early rather than leaving it until the recovery vehicle arrives.','tip':'Have the registration, keys and any available paperwork together before your collection appointment. Check the agreed price and payment arrangements before handover.'},
'smethwick':{'name':'Smethwick','area':'Smethwick and the surrounding Sandwell area','places':['Bearwood','Cape Hill','Warley','Galton Bridge','Soho','Londonderry'],'intro':'Clear some space with a straightforward scrap car quote request in Smethwick. Start with the registration, then add the vehicle condition and collection postcode.','heading':'Collection starts with the right details','body':'Around Smethwick, the car may be tucked away behind a terrace, in a shared yard or at a local repairer. Before collection is booked, confirm the access width and whether the car can roll out safely.','detail':'If the car is damaged, choose the damaged option even if the engine still starts. Tell the collection team about any leaking fluids or unsafe bodywork before a collection date is agreed.','tip':'Do not leave the keys in the vehicle while waiting for collection. Arrange a safe handover and confirm the identity of the collector.'}}
faq_items=[('How much is my scrap car worth?','Your quote depends on the vehicle, its condition, any missing parts and the collection location. Enter your registration and a few details to request a price. There is no automatic vehicle valuation in this website preview.'),('Can I request a quote if my car doesn’t start?','Yes. Choose “Not running” on the quote form. If the car is damaged or missing parts, choose that option instead. Before collection, explain whether it rolls and steers so the right recovery arrangements can be discussed.'),('What if I don’t have the V5C logbook?','Select “No” or “Not sure” in the form. Confirm the alternative documents needed with the receiving facility before collection. See our <a href="/guides/scrap-car-without-v5c/">guide to a missing V5C</a> for the next steps.'),('Do I have to provide a phone number?','No. Email is required, but a phone number is optional. You can request your quote without agreeing to marketing messages.'),('Am I committed when I request a quote?','No. A quote request is not a sale or a collection booking. Review the price, any collection costs, payment arrangements and the receiving facility before you decide.'),('What happens to my car after collection?','A car being scrapped must go to an authorised treatment facility. Confirm the receiving facility and ask about the relevant paperwork before handover. Our <a href="/guides/car-recycling/">recycling guide</a> explains what to check.')]
def faqs(items=None):return '<div class="faq-list">'+''.join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in (items or faq_items))+'</div>'
def steps():
 data=[('file','Tell us about your car','Start with your registration. Add the condition, collection postcode and your email. No long forms.','Just the details that matter'),('truck','Agree your quote & collection','Review the price and collection details. If you’re happy, arrange a time and place that works for you.','You decide whether to go ahead'),('bank','Hand over. Get paid. Move on.','Confirm payment arrangements and paperwork before handover. Then enjoy a little more space on your drive.','A clear finish, without the guesswork')]
 return '<div class="steps">'+''.join(f'<div class="step"><div class="step-top"><span class="step-num">0{i+1}</span>{icon(ic)}</div><h3>{h}</h3><p>{p}</p><div class="tiny">{icon("check")}{s}</div></div>' for i,(ic,h,p,s) in enumerate(data))+'</div>'
