def guide_cards():return '<div class="guide-grid">'+''.join(f'<a href="/guides/{slug}/" class="guide-card"><div class="guide-art">{icon(ic)}</div><span class="category">{cat}</span><h3>{title}</h3><p>{desc}</p><div class="read">{time}{arrow()}</div></a>' for slug,ic,cat,title,desc,time in guides)+'</div>'
