def page(path,title,desc,body,active='',quote=False,article=False):
 if LIVE and path in ('/privacy/','/terms/'):
  desc='How we handle your quote details.' if path=='/privacy/' else 'Clear terms for requesting a car quote.'
 navitems=[('How it works','/how-it-works/'),('Areas','/locations/'),('FAQs','/faqs/')] if path=='/' else [('How it works','/how-it-works/'),('Areas we cover','/locations/'),('Helpful guides','/guides/'),('About us','/about/')]
 nav=''.join(f'<a href="{u}"'+(' class="active" aria-current="page"' if active==u else '')+f'>{n}</a>' for n,u in navitems)
 if LIVE and path=='/quote/':
  body=body.replace('id="quote-form"','id="quote-form" data-endpoint="/api/quote"').replace('Review my request','Request my quote').replace('Preview only. Your details won’t be sent.','We use your details to answer your request. <a href="/privacy/">Privacy policy</a>.').replace('Enable JavaScript to review your request. Nothing is sent from this preview.','Enable JavaScript to request your quote.')
 schema={'@context':'https://schema.org','@type':'WebPage','name':title,'description':desc,'url':ORIGIN+path,'isPartOf':{'@type':'WebSite','name':BRAND,'url':ORIGIN}}
 if LIVE and path=='/':
  business={'@type':'LocalBusiness','@id':ORIGIN+'/#business','name':BRAND,'legalName':SETTINGS['legal_name'],'url':ORIGIN,'email':SETTINGS['contact_email'],'address':SETTINGS['business_address'],'sameAs':[SETTINGS['google_business_url']],'areaServed':[{'@type':'AdministrativeArea','name':name} for name in ['Birmingham','Sandwell','Dudley','Walsall','Wolverhampton']]}
  if SETTINGS.get('contact_phone'):business['telephone']=SETTINGS['contact_phone']
  schema={'@context':'https://schema.org','@graph':[schema,business]}
 content=f'''<!doctype html><html lang="en-GB"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)} | ScrapLocal</title><meta name="description" content="{html.escape(desc,quote=True)}"><meta name="robots" content="{'index, follow' if PUBLISHED and not quote else 'noindex, nofollow'}"><meta name="theme-color" content="#153f32"><link rel="canonical" href="{ORIGIN+path}"><meta property="og:title" content="{html.escape(title,quote=True)} | ScrapLocal"><meta property="og:description" content="{html.escape(desc,quote=True)}"><meta property="og:type" content="website"><meta property="og:url" content="{ORIGIN+path}"><meta property="og:image" content="{ORIGIN}/assets/social.svg"><link rel="icon" type="image/svg+xml" href="/assets/favicon.svg"><link rel="stylesheet" href="/assets/style.css"><script src="/assets/coverage.js" defer></script><script src="/assets/app.js" defer></script><script type="application/ld+json">{json.dumps(schema)}</script></head><body class="{'homepage' if path=='/' else 'quote-page' if quote else ''}"><a class="skip" href="#main">Skip to content</a><div class="preview-bar"><span></span>Website preview · Quote requests aren’t sent yet.</div><header class="header"><nav class="nav wrap" aria-label="Main navigation">{logo()}{'' if quote else f'<div class="nav-links" id="nav-links">{nav}</div><button class="menu-button" aria-label="Open menu" aria-expanded="false" aria-controls="nav-links">{icon("menu")}</button>'}</nav></header><main id="main">{body}</main>{quote_footer() if quote else home_footer() if path=='/' else footer()}</body></html>'''
 if LIVE:
  content=content.replace('<div class="preview-bar"><span></span>Website preview · Quote requests aren’t sent yet.</div>','').replace('Working brand · website preview.','').replace(' · Website preview','')
  if path=='/contact/':
   start=content.find('<div class="notice">This is a website preview.')
   if start!=-1:
    end=content.find('</div>',start)+6
    content=content[:start]+business_details(SETTINGS)+content[end:]
  if path=='/about/':
   start=content.find('<div class="notice"><strong>About this first version</strong>')
   if start!=-1:
    end=content.find('</div>',start)+6
    content=content[:start]+business_details(SETTINGS)+content[end:]
  content=content.replace('in this preview.','on this website.').replace('This form prepares a quote request. It does not look up the vehicle or generate an automated price. Email delivery will be connected in a later phase.','We prepare your quote from the details you provide and reply by email. There is no automated valuation.').replace('There is no automatic vehicle valuation in this website preview.','We prepare individual quotes; there is no automated valuation.').replace('This website preview does not calculate prices or retrieve vehicle records. The form prepares a request for an individual quote.','Your quote is prepared individually from the details you provide.').replace('This first version focuses on Birmingham','We focus on Birmingham')
 if BRAND!='ScrapLocal':content=content.replace('scrap<em>local</em>',html.escape(BRAND)).replace('ScrapLocal',html.escape(BRAND))
 pages[path]={'title':title,'desc':desc}
 target=DIST/(path.lstrip('/')+'index.html' if path.endswith('/') else path.lstrip('/'))
 target.parent.mkdir(parents=True,exist_ok=True);target.write_text(content)
def hero(title,lead,section='Good to know',form=False,bread=None):
 crumbs=[('Home','/')]+(bread or [])
 return '<section class="page-hero"><div class="wrap"><div class="breadcrumb">'+'<span>/</span>'.join(f'<a href="{u}">{n}</a>' if u else f'<span>{n}</span>' for n,u in crumbs)+f'</div><span class="eyebrow"><span class="dot"></span>{section}</span><h1>{title}</h1><p class="lead">{lead}</p>'+ (start_form('page') if form else '')+'</div></section>'
