home=f'''<div class="simple-home"><section class="hero"><div class="wrap"><div class="hero-grid"><div class="hero-copy"><span class="eyebrow"><span class="dot"></span>West Midlands</span><h1>Sell your car.<span>Quick & easy.</span></h1><p>Get a quote. Arrange pickup. Get paid.</p>{start_form('hero', label='Get Quote', show_note=False)}<p class="pickup-note">{icon('clock')}Same-day pickup may be available.</p></div><div class="hero-art"><img src="/assets/car-value.svg" width="720" height="610" alt="A car turning into money, illustrated with an arrow and a large pound coin" fetchpriority="high"></div></div><div class="hero-trust"><div>{icon('check')}No obligation</div><div>{icon('truck')}Local collection</div><div>{icon('shield')}You approve the price</div></div></div></section>
<section id="steps" class="home-steps section soft"><div class="wrap"><div class="section-head"><h2>Sell your car in 3 steps.</h2>{link('How it works','/how-it-works/')}</div><div class="steps">'''+''.join(f'<div class="step"><div class="step-top"><span class="step-num">0{i+1}</span>{icon(ic)}</div><h3>{title}</h3><p>{copy}</p></div>' for i,(ic,title,copy) in enumerate(home_steps))+f'''</div></div></section>
<section class="home-areas"><div class="wrap"><h2>Pickup across the West Midlands.</h2><div class="home-area-links">'''+''.join(f'<a href="/locations/{slug}/">{v["name"]}{arrow()}</a>' for slug,v in locations.items())+f'''</div></div></section>
<section class="home-faqs"><div class="wrap faq-layout"><div><h2>A few quick answers.</h2>{link('All FAQs','/faqs/')}</div>{faqs(home_faqs)}</div></section>
<section class="home-last-call"><div class="wrap"><h2>Ready to sell?</h2>{link('Get my quote','/quote/','btn')}</div></section></div>'''
page('/','Sell your scrap car quickly & easily in the West Midlands','Sell your scrap car quickly and easily in the West Midlands. Request a quote and ask about same-day collection, subject to location and availability.',home)
# Quote form: intentionally no delivery or persistent personal-data storage in preview.
quote_conditions=[('car','running','Running','Starts & complete'),('engine','non-runner','Not running','Won’t start'),('damage','damaged','Damaged','Accident or bodywork'),('parts','incomplete','Missing parts','Components removed')]
quote=f'''<section class="quote-section"><div class="wrap"><div id="quote-content" class="quote-layout"><form class="quote-form" id="quote-form"><section class="quote-block"><div class="field field-reg"><h1 class="quote-registration-title"><label for="quote-reg">Get cash for:</label></h1><div class="plate"><div class="gb" aria-hidden="true"><span>✦</span>UK</div><input id="quote-reg" name="reg" required maxlength="10" placeholder="ENTER REG" autocomplete="off" spellcheck="false" autocapitalize="characters"></div></div><fieldset class="field condition-field"><legend>What condition is it in?</legend><div class="condition-options">'''+''.join(f'<label class="option condition-option"><input type="radio" name="condition" value="{value}" required>{icon(ic)}<span><strong>{title}</strong><small>{hint}</small></span></label>' for ic,value,title,hint in quote_conditions)+f'''</div></fieldset><fieldset class="field v5-field"><legend>Do you have the V5C logbook?</legend><div class="radio-row"><label class="option"><input type="radio" name="v5c" value="yes" required>Yes</label><label class="option"><input type="radio" name="v5c" value="no">No</label><label class="option"><input type="radio" name="v5c" value="unsure">Not sure</label></div><small>Missing it? You can still request a quote.</small></fieldset></section><section class="quote-block"><div class="quote-block-heading"><span class="block-icon">{icon('pin')}</span><h2>Pickup & contact</h2></div><div class="field"><label for="postcode">Pickup postcode</label><input id="postcode" name="postcode" required maxlength="10" placeholder="e.g. B70 0AA" autocomplete="postal-code" autocapitalize="characters" spellcheck="false"><small>Where the car is parked.</small></div><div class="field"><label for="email">Email address</label><input id="email" name="email" type="email" required maxlength="254" placeholder="you@example.com" autocomplete="email" inputmode="email"></div><div class="field"><label for="phone">Phone number <em>Optional</em></label><input id="phone" name="phone" type="tel" maxlength="25" placeholder="e.g. 07700 900000" autocomplete="tel" inputmode="tel"></div></section><div class="honeypot" aria-hidden="true"><label for="website">Leave this empty</label><input id="website" name="website" tabindex="-1" autocomplete="off"></div><div class="form-bottom"><p class="error" id="form-error" role="alert" hidden></p><button class="btn" type="submit" disabled>Review my request {arrow()}</button><p class="form-reassurance">{icon('lock')}No obligation to sell.</p><p class="quote-preview-note">Preview only. Your details won’t be sent.</p></div></form></div><noscript><p class="demo-note">Enable JavaScript to review your request. Nothing is sent from this preview.</p></noscript></div></section>'''
page('/quote/','Request your scrap car quote','Enter your vehicle registration, V5C status, car condition and collection postcode. Add your email and an optional phone number.',quote,quote=True)
process=hero('Sell your car.<br>Quickly. Easily.','A short quote request. A convenient pickup. Three clear steps to selling your car, with same-day collection potentially available depending on your location and the schedule.','How it works',True,[('How it works',None)])+f'<section class="section soft"><div class="wrap">{steps()}</div></section><section class="section"><div class="wrap two-col"><article class="article"><h2>Before collection day</h2><p>Check that the vehicle details match your quote. Confirm the agreed price, whether collection has a cost, the payment method and when payment will arrive. Tell the collection team if anything has changed.</p><h3>A quick collection checklist</h3><ul><li>Remove your personal belongings and check every storage compartment.</li><li>Have your keys, identification and any available vehicle documents ready.</li><li>Explain access restrictions and whether the car rolls and steers.</li><li>Arrange to retain a private plate beforehand if you want to keep it.</li><li>Confirm who is receiving the vehicle and what paperwork you will get.</li></ul><h2>Keep a record of the handover</h2><p>Keep your agreed quote and the collection details together. Check the DVLA notification steps for your situation and retain the relevant confirmation.</p><p>For the official process, read <a href="https://www.gov.uk/scrapped-and-written-off-vehicles" target="_blank" rel="noopener noreferrer">GOV.UK’s guide to scrapping a vehicle</a>.</p></article>{sidebar()}</div></section>'+cta()
page('/how-it-works/','How to scrap your car in 3 simple steps','Find out how a scrap car quote, collection and handover work. Prepare your car, check the paperwork and understand the next steps.',process,active='/how-it-works/')
area_cards=''.join(f'<div class="info-card">{icon("pin")}<h2>{v["name"]}</h2><p>{v["intro"]}</p>{link("Explore "+v["name"],f"/locations/{k}/")}</div>' for k,v in locations.items())
page('/locations/','Scrap car collection across the West Midlands','Explore scrap car quote requests in Birmingham, West Bromwich, Dudley, Walsall, Wolverhampton and Smethwick.',hero('Sell your car.<br>We’ll keep it local.','Explore our West Midlands collection areas. Use the postcode where your vehicle is waiting so availability can be confirmed with your quote.','Areas we cover',False,[('Locations',None)])+f'<section class="section"><div class="wrap cards-grid">{area_cards}</div></section>'+cta(),active='/locations/')
for slug,v in locations.items():
 body=hero(f'Scrap your car in<br>{v["name"]}.',v['intro'],'Your local scrap car quote',True,[('Locations','/locations/'),(v['name'],None)])
 body+=f'<section class="section"><div class="wrap two-col"><article class="article"><h2>{v["heading"]}</h2><p>{v["body"]}</p><p>{v["detail"]}</p><div class="notice"><strong>A useful local collection tip</strong><br>{v["tip"]}</div><h2>In and around {v["name"]}</h2><p>You can request a quote for a vehicle in these neighbourhoods. Collection availability, access and any costs are confirmed before booking.</p><div class="local-suburbs">'+''.join(f'<span>{n}</span>' for n in v['places'])+f'</div><h2>What to include in your request</h2><p>Your registration, V5C status, one of four condition choices and the collection postcode help prepare the next step. Email is required; a phone number is optional.</p><h2>A few local collection questions</h2>'+faqs([(f'Can I request collection of a non-runner in {v["name"]}?','Yes. Use the form to describe the condition and location. Collection is only arranged after availability, access and the quote have been agreed.'),(f'What if the car is at a garage in {v["name"]}?','Use the garage’s collection postcode. Agree the release of the vehicle with the garage and discuss any fees with them before a collection is booked.'),('Will I get a price on screen?','This first version prepares a request for a quote. It does not look up the vehicle or generate an automated price. Email delivery will be connected in a later phase.')])+f'</article>{sidebar()}</div></section><section class="section soft"><div class="wrap"><div class="section-head"><div><span class="eyebrow">One clear process</span><h2>Three steps to moving on.</h2></div></div>{steps()}</div></section>'+cta()
 page(f'/locations/{slug}/',f'Scrap my car {v["name"]} — Request a collection quote',f'Request a scrap car quote in {v["name"]}. Enter your registration, choose your car condition and add the collection postcode. Phone number optional.',body,active='/locations/')
page('/guides/','Helpful scrap car guides','Understand scrap car prices, V5C paperwork and car recycling with clear, practical guides.',hero('A little know-how.<br>A lot less hassle.','The paperwork, the price, the next steps. Practical reading to help you feel comfortable before you sell.','Scrap car guides',False,[('Guides',None)])+f'<section class="section"><div class="wrap">{guide_cards()}</div></section>'+cta(),active='/guides/')
articles={
'scrap-car-without-v5c':('Can I scrap my car without a V5C?','Missing a logbook does not have to stop you asking for a quote. Here is what to clarify before arranging a collection.', '''<h2>Tell us the logbook is missing</h2><p>Select “No” or “Not sure” under the V5C question. Being clear at the start means the paperwork can be discussed before you make collection arrangements.</p><h2>Check the documents before booking</h2><p>Ask the receiving facility what identification and ownership evidence it needs. Requirements must be confirmed for your circumstances, especially if you are handling a vehicle for someone else.</p><div class="notice">The V5C records the registered keeper. It is not, by itself, proof that someone owns a vehicle.</div><h2>Keep the DVLA notification in mind</h2><p>You still need to notify DVLA when a vehicle is scrapped. If the logbook is missing, follow the official instructions for your situation rather than assuming the collection completes the notification.</p><h2>Before the vehicle leaves</h2><ul><li>Confirm that the car can be accepted without the V5C.</li><li>Agree the alternative documents and have them ready.</li><li>Keep the receiving facility’s name and address.</li><li>Keep your handover and notification records.</li></ul><p>Read the <a href="https://www.gov.uk/sold-bought-vehicle" target="_blank" rel="noopener noreferrer">official DVLA guidance on selling or transferring a vehicle</a> and the <a href="https://www.gov.uk/scrapped-and-written-off-vehicles" target="_blank" rel="noopener noreferrer">vehicle scrapping process</a> for current instructions.</p>'''),
'scrap-car-prices':('What affects the price of a scrap car?','A useful quote starts with an accurate description. These are the details worth getting right.', '''<h2>One car, several things to consider</h2><p>A scrap car quote is specific to the vehicle and the collection. A generic average cannot tell you exactly what your particular car is worth.</p><h3>The vehicle itself</h3><p>Make, model, age and size help describe the vehicle. A buyer may consider the material and any usable components when deciding what to offer.</p><h3>Its current condition</h3><p>A complete running car is different from a damaged shell. Explain whether the car starts and tell the buyer about missing components. Choose the closest of the four condition options when you request your quote.</p><h3>Where it needs collecting</h3><p>A postcode helps establish the location. Access restrictions, missing wheels or a car that cannot roll may affect the collection arrangements and overall offer.</p><h2>Compare the whole offer</h2><p>Look beyond a headline number. Ask whether collection is included, whether any deductions apply and how long the offer remains valid. Confirm the amount you will actually receive before handover.</p><div class="notice">This website preview does not calculate prices or retrieve vehicle records. The form prepares a request for an individual quote.</div><h2>Give an accurate description</h2><p>If the condition changes after a quote is agreed, tell the buyer before collection. Clear details at the start help avoid a disagreement when the recovery vehicle arrives.</p>'''),
'car-recycling':('Your old car. Its next chapter.','Understand the receiving facility, the paperwork and the checks to make before your vehicle is recycled.', '''<h2>Start with the receiving facility</h2><p>End-of-life vehicles must be scrapped at an authorised treatment facility (ATF). Check the facility’s details before you agree to hand over your car.</p><p>You can use the <a href="https://www.gov.uk/find-vehicle-scrapyard" target="_blank" rel="noopener noreferrer">official vehicle scrapyard finder</a> to look for an ATF.</p><h2>Ask which paperwork applies</h2><p>Ask the receiving facility whether your vehicle will be destroyed or repaired and sold. The paperwork depends on that decision. For a qualifying vehicle that is destroyed, a Certificate of Destruction records that outcome.</p><h2>Do not leave loose ends</h2><p>Confirm the payment arrangements, keep a record of the handover and follow the DVLA notification process. Remove any personal belongings and deal with a private registration you want to keep before transfer.</p><div class="notice">A collection is one step in the process. Make sure you understand who receives the vehicle and what confirmation you should expect.</div><h2>Keep the official guidance handy</h2><p>For current rules on receiving facilities and documentation, read <a href="https://www.gov.uk/scrapped-and-written-off-vehicles/where-you-can-scrap-your-vehicle" target="_blank" rel="noopener noreferrer">GOV.UK’s vehicle scrapping guidance</a>.</p>''')}
for slug,(title,intro,article) in articles.items():
 page(f'/guides/{slug}/',title,intro,hero(title,intro,'Scrap car guide · 3 min read',False,[('Guides','/guides/'),(title,None)])+f'<section class="section"><div class="wrap two-col"><article class="article">{article}<p><small>Reviewed October 2026. Check the linked official guidance before arranging your sale.</small></p>{link("Back to all guides","/guides/")}</article>{sidebar()}</div></section>'+cta(),active='/guides/')
about=hero('Selling your car,<br>made simpler.','Less chasing. Less guesswork. More clarity about what happens next. That is the idea behind ScrapLocal.','About us',False,[('About us',None)])+f'''<section class="section"><div class="wrap two-col"><article class="article"><h2>Built around the person selling</h2><p>Selling a car you no longer need should be quick and easy. ScrapLocal starts with a short quote request, followed by a convenient collection. Same-day pickup may be available, depending on your location and the collection schedule.</p><h2>Simple where it should be</h2><p>Start with your registration. Pick one of four vehicle conditions. Tell us where the car is, whether you have the V5C and how to reach you. There is no requirement to leave a phone number.</p><h2>Clear where it counts</h2><p>A quote request is not a commitment to sell. Before you decide, you should know the price, any collection costs, the payment arrangements and the receiving facility.</p><h2>Local from the start</h2><p>This first version focuses on Birmingham and the surrounding West Midlands. Each local page offers practical collection guidance rather than a wall of repeated sales copy.</p><div class="notice"><strong>About this first version</strong><br>ScrapLocal is a working brand for this website preview. Quote delivery is not connected yet. Business identity, collection terms, licences and genuine customer reviews will be added and checked before public launch.</div></article>{sidebar()}</div></section>'''+cta()
page('/about/','About ScrapLocal — A simpler scrap car experience','Meet the idea behind ScrapLocal: clear quote requests, straightforward collection information and a local West Midlands focus.',about,active='/about/')
page('/faqs/','Scrap car FAQs — Clear answers before you sell','Answers about scrap car quotes, V5C documents, non-running cars, collection, contact details and recycling.',hero('Your questions.<br>Without the jargon.','A few useful answers before you take the next step. Still deciding? Your quote request comes with no commitment to sell.','Frequently asked questions',False,[('FAQs',None)])+f'<section class="section"><div class="wrap two-col"><div>{faqs()}</div>{sidebar()}</div></section>'+cta())
page('/contact/','Contact & quote requests','Start a scrap car quote request, find answers about selling your vehicle and understand how to get in touch in this preview.',hero('Let’s get you<br>moving forward.','Start with a quote request, or find the answer to a question before you begin.','Contact',False,[('Contact',None)])+f'<section class="section"><div class="wrap"><div class="contact-cards"><div class="info-card">{icon("car")}<h2>Looking for a scrap car quote?</h2><p>Your registration, vehicle condition and collection postcode are the best place to start. Add your email address and an optional phone number.</p>{link("Start my quote request","/quote/","btn")}</div><div class="info-card">{icon("help")}<h2>Have a question first?</h2><p>Find out about V5C paperwork, collection and what happens after you request a quote. Take a moment to understand the next steps.</p>{link("Browse our answers","/faqs/","btn outline")}</div></div><div class="article" style="margin-top:40px"><div class="notice">This is a website preview. The quote form does not send requests yet. For enquiries, email <a href="mailto:enquiry@scrapcarsorted.co.uk">enquiry@scrapcarsorted.co.uk</a>.</div></div></div></section>')
privacy='''<h2>This website preview</h2><p>Quote requests are not sent to the business. The form checks the pickup postcode and uses the details you enter to display a summary on your current page. There is no vehicle lookup, email delivery or application database connected.</p><h2>What you can enter</h2><p>The form asks for a vehicle registration, V5C status, condition, collection postcode, email address and optional phone number. Use example details while testing the preview. Do not enter sensitive information.</p><h2>What is stored</h2><p>The application does not save contact details in browser storage. The registration you enter on the first page is passed in the next page’s URL. It can appear in browser history and hosting access logs. Do not put contact details in that URL.</p><h2>Postcode coverage checks</h2><p>The pickup postcode is sent to Postcodes.io to check whether it belongs to our collection area. Your registration, email and phone number are not sent to that service. If the check is unavailable, the request cannot continue until it can be checked.</p><h2>Cookies and third-party services</h2><p>This application does not add analytics, advertising or marketing cookies. The hosting platform may use cookies and technical logs to provide private access and operate the site. Fonts are served from this website; no request is sent to Google Fonts.</p><h2>Before public launch</h2><p>A production privacy notice must identify the business responsible for personal data, how to contact it, the purpose and lawful basis for processing, who receives data, retention periods and how to exercise data rights. Those details will be completed when the business identity and quote delivery provider are confirmed.</p>'''
if LIVE:privacy,live_terms=production_policies(SETTINGS)
page('/privacy/','Privacy policy' if LIVE else 'Preview privacy & cookie information','How the ScrapLocal website preview handles information entered in the quote form.',hero('Your details.<br>Handled clearly.','How we handle your quote details.' if LIVE else 'Privacy and cookie information for this website preview.','Privacy & cookies',False,[('Privacy',None)])+f'<section class="section"><div class="wrap article">{privacy}</div></section>')
terms='''<h2>A preview, not a collection booking</h2><p>This version lets you explore the website and test the quote journey. No quote request is delivered, no price is generated and no sale or collection agreement is made through the preview.</p><h2>Working brand and service information</h2><p>ScrapLocal is a working name. Business identity, operating arrangements, actual collection coverage and service terms must be confirmed before public launch. There are no claimed customer ratings, review totals or operating licences in this preview.</p><h2>Guidance on this website</h2><p>The guides offer general information to help you prepare questions. Follow the linked official guidance and confirm the specific requirements with the receiving facility before arranging a vehicle handover.</p><h2>Future quote terms</h2><p>Live service terms will explain how quotes are prepared and accepted, their validity, collection conditions, payment arrangements, cancellations and how any disputes are handled.</p>'''
if LIVE:terms=live_terms
page('/terms/','Quote request terms' if LIVE else 'Website preview terms','Understand the scope of the ScrapLocal website preview and quote journey.',hero('A few clear<br>ground rules.','Clear terms for requesting a quote.' if LIVE else 'What this website preview does, and what will be confirmed before the live service launches.','Website terms',False,[('Terms',None)])+f'<section class="section"><div class="wrap article">{terms}</div></section>')
page('/sitemap/','Website sitemap','Explore ScrapLocal’s quote form, local collection pages, selling guides and website information.',hero('Everything,<br>in one place.','Find your way around ScrapLocal.','Sitemap',False,[('Sitemap',None)])+'<section class="section"><div class="wrap article"><ul>'+''.join(f'<li><a href="{path}">{d["title"]}</a></li>' for path,d in pages.items())+'</ul></div></section>')
